// Geeft de gecombineerde FAQ-lijst voor een segment+taal (segment-specifiek eerst, dan algemeen, gededupliceerd op vraag).
export function faqFor(segment, lang){
  var g = (GENERAL[lang] || GENERAL.nl);
  var seg = (BY_SEGMENT[segment] && (BY_SEGMENT[segment][lang] || BY_SEGMENT[segment].nl)) || [];
  var seen = {}; var out = [];
  seg.concat(g).forEach(function(f){ var k=(f.q||'').trim().toLowerCase(); if(!seen[k]){ seen[k]=1; out.push(f); } });
  return out;
}
// Alleen de 10 algemene vragen (voor assessmentpagina's).
export function generalFaq(lang){ return GENERAL[lang] || GENERAL.nl; }
